{"studies":[
{"protocolSection":{"identificationModule":{"nctId":"NCT00391092","orgStudyIdInfo":{"id":"BO20231"},"organization":{"fullName":"Hoffmann-La Roche","class":"INDUSTRY"},"briefTitle":"A Study of Avastin (Bevacizumab) in Combination With Herceptin (Trastuzumab)/Docetaxel in Patients With HER2 Positive Metastatic Breast Cancer.","officialTitle":"A Randomized, Open-label Study to Compare the Effect of First-line Treatment With Avastin in Combination With Herceptin/Docetaxel and Herceptin/Docetaxel Alone on Progression-free Survival in Patients With HER2 Positive Locally Recurrent or Metastatic Breast Cancer."},"statusModule":{"statusVerifiedDate":"2015-08","overallStatus":"COMPLETED","expandedAccessInfo":{"hasExpandedAccess":false},"startDateStruct":{"date":"2006-09"},"primaryCompletionDateStruct":{"date":"2014-08","type":"ACTUAL"},"completionDateStruct":{"date":"2014-08","type":"ACTUAL"},"studyFirstSubmitDate":"2006-10-20","studyFirstSubmitQcDate":"2006-10-20","studyFirstPostDateStruct":{"date":"2006-10-23","type":"ESTIMATED"},"resultsFirstSubmitDate":"2015-07-21","resultsFirstSubmitQcDate":"2015-07-21","resultsFirstPostDateStruct":{"date":"2015-08-14","type":"ESTIMATED"},"lastUpdateSubmitDate":"2015-08-21","lastUpdatePostDateStruct":{"date":"2015-08-28","type":"ESTIMATED"}},"sponsorCollaboratorsModule":{"responsibleParty":{"type":"SPONSOR"},"leadSponsor":{"name":"Hoffmann-La Roche","class":"INDUSTRY"}},"descriptionModule":{"briefSummary":"This 2 arm study will compare the efficacy and safety of Avastin plus Herceptin/docetaxel, versus Herceptin/docetaxel alone, in patients with HER2 positive locally recurrent or metastatic breast cancer who have not received prior chemotherapy for their metastatic disease. Patients will be randomized 1:1 to receive either Avastin (15mg/kg iv q3weeks) + Herceptin (8mg/kg iv loading dose and 6mg/kg iv q3weeks maintenance) + docetaxel (100mg/m2 iv q3weeks) or Herceptin + docetaxel alone. The anticipated time on study treatment is until disease progression, and the target sample size is 100-500 individuals."},"conditionsModule":{"conditions":["Breast Cancer"]},"designModule":{"studyType":"INTERVENTIONAL","phases":["PHASE3"],"designInfo":{"allocation":"RANDOMIZED","interventionModel":"PARALLEL","primaryPurpose":"TREATMENT","maskingInfo":{"masking":"NONE"}},"enrollmentInfo":{"count":424,"type":"ACTUAL"}},"armsInterventionsModule":{"armGroups":[{"label":"1","type":"EXPERIMENTAL","interventionNames":["Drug: bevacizumab [Avastin]","Drug: Docetaxel","Drug: Herceptin"]},{"label":"2","type":"ACTIVE_COMPARATOR","interventionNames":["Drug: Docetaxel","Drug: Herceptin"]}],"interventions":[{"type":"DRUG","name":"bevacizumab [Avastin]","description":"15mg/kg iv every 3 weeks","armGroupLabels":["1"]},{"type":"DRUG","name":"Docetaxel","description":"100mg/m2 iv every 3 weeks","armGroupLabels":["1","2"]},{"type":"DRUG","name":"Herceptin","description":"8mg/kg iv loading dose, followed by 6mg/kg iv every 3 weeks","armGroupLabels":["1","2"]}]},"outcomesModule":{"primaryOutcomes":[{"measure":"Progression Free Survival (PFS)","description":"PFS was defined as the time from randomization to time of first documented disease progression (unequivocal progression of existing non-target lesions) or death, whichever occurred first as assessed by Response Evaluation Criteria in Solid Tumors version 1.0 (RECIST v1.0). Progressive disease is defined using RECIST v1.0 as at least a 20% increase in the sum of the longest diameter of target lesions, taking as reference the smallest sum longest diameter recorded since the treatment started. Primary PFS variable was defined based on the investigators' assessments and the statistical conclusions on the primary efficacy endpoint were based on investigator assessed PFS. PFS was estimated using Kaplan-Meier methods.","timeFrame":"Every 9 weeks up to Week 36, thereafter every 12 weeks until disease progression (up to the clinical cutoff of 30 June 2011, up to 4.75 years)"}],"secondaryOutcomes":[{"measure":"Overall Survival (OS)","description":"OS was defined as the time from randomization to the date of death, regardless of the cause of death. OS was estimated using Kaplan-Meier methods.","timeFrame":"Every 9 weeks up to Week 36, thereafter every 12 weeks until disease progression (up to the clinical cutoff of 30 June 2011, up to 4.75 years)"},{"measure":"Percentage of Participants With a Best Overall Response (OR) of Confirmed Complete Response (CR) or Partial Response (PR) in Participants With Measurable Disease at Baseline","description":"Best OR was assessed using RECIST v1.0 criteria. Participants were classified as responders if their best OR was either confirmed CR (disappearance of all target lesions) or confirmed PR (at least a 30% decrease in the sum of the longest diameter \[LD\] of target lesions, taking as reference the baseline sum LD). Participants without any post-baseline assessments were regarded as non-responders. The 95% CI for the one sample binomial using Pearson-Clopper method.","timeFrame":"Every 9 weeks up to Week 36, thereafter every 12 weeks until disease progression (up to the clinical cutoff of 30 June 2011, up to 4.75 years)"},{"measure":"Duration of Response (DR)","description":"DR was defined as the time when response (CR or PR per RECIST v1.0) was first documented to the date of disease progression per RECIST v1.0 (unequivocal progression of existing non-target lesions) or death. Progressive disease is defined using RECIST v1.0 as at least a 20% increase in the sum of the longest diameter of target lesions, taking as reference the smallest sum longest diameter recorded since the treatment started.","timeFrame":"Every 9 weeks up to Week 36, thereafter every 12 weeks until disease progression (up to the clinical cutoff of 30 June 2011, up to 4.75 years)"},{"measure":"Time to Treatment Failure (TTF)","description":"TTF was defined as the time between randomization and date of disease progression (per RECIST v1.0; unequivocal progression of existing non-target lesions), death, or withdrawal of treatment due to adverse events, withdrawal of informed consent, insufficient therapeutic response, refusal of treatment/failure to co-operate, or failure to return, whichever occurred first. Progressive disease is defined using RECIST v1.0 as at least a 20% increase in the sum of the longest diameter of target lesions, taking as reference the smallest sum longest diameter recorded since the treatment started.","timeFrame":"Every 9 weeks up to Week 36, thereafter every 12 weeks until disease progression (up to the clinical cutoff of 30 June 2011, up to 4.75 years)"},{"measure":"Functional Assessment of Cancer Therapy - Generic (FACT-G) and Functional Assessment of Cancer Therapy - Breast (FACT-B) Subscale Scores","description":"FACT-G is core questionnaire of Functional Assessment of Chronic Illness Therapy (FACIT) measurement system to evaluate quality of life (QoL) in cancer population. FACT-G consisted of 27 questions grouped in 4 domains of general Health-Related QoL (HRQoL): Physical Well-being (PWB), Social/Family Well-Being (SWB), Emotional Well-Being (EWB) and Functional Well-Being (FWB); each ranged from 0 (not at all) to 4 (very much). FACT-G ranged between 0-108. Since questions could be reversed coded, as appropriate, before calculating FACT-G, 0 and 108 could be considered worst and best health states. FACT -B is used for assessment of HRQoL in participants with breast cancer. It consists of 36 items, summarized to 5 subscales: 7 items for each physical, functional, social/family; all 3 ranged from 0-28, emotional (6 items) ranged from 0-24, and breast cancer subscale (9 items) ranged from 0-36. All single-item measures ranges from 0-144. High scale score represents a better QoL.","timeFrame":"Baseline, Cycles 3, 5, 11, and post progressive disease (PD; 14 to 28 days after disease progression [up to the clinical cutoff of 30 June 2011, up to 4.75 years])"},{"measure":"Change From Baseline for FACT-G and FACT-B","description":"FACT-G is core questionnaire of Functional Assessment of Chronic Illness Therapy (FACIT) measurement system to evaluate quality of life (QoL) in cancer population. FACT-G consisted of 27 questions grouped in 4 domains of general Health-Related QoL (HRQoL): Physical Well-being (PWB), Social/Family Well-Being (SWB), Emotional Well-Being (EWB) and Functional Well-Being (FWB); each ranged from 0 (not at all) to 4 (very much). FACT-G ranged between 0-108. Since questions could be reversed coded, as appropriate, before calculating FACT-G, 0 and 108 could be considered worst and best health states. FACT -B is used for assessment of HRQoL in participants with breast cancer. It consists of 36 items, summarized to 5 subscales: 7 items for each physical, functional, social/family; all 3 ranged from 0-28, emotional (6 items) ranged from 0-24, and breast cancer subscale (9 items) ranged from 0-36. All single-item measures ranges from 0-144. High scale score represents a better QoL.","timeFrame":"Baseline, Cycles 3, 5, 11, and post PD (14 to 28 days after disease progression [up to the clinical cutoff of 30 June 2011, up to 4.75 years])"}]},"eligibilityModule":{"eligibilityCriteria":"Inclusion Criteria:

* adult patients, \>=18 years of age;
* HER2 positive breast cancer with locally recurrent or metastatic lesions;
* eligible for chemotherapy;
* baseline LVEF \>=50%.

Exclusion Criteria:

* previous chemotherapy for metastatic or locally recurrent breast cancer;
* previous radiotherapy for metastatic breast cancer (except for metastatic bone pain relief);
* other primary tumor within last 5 years, with the exception of basal or squamous skin cancer, or in situ cancer of the cervix;
* clinically significant cardiovascular disease;
* chronic daily treatment with aspirin (\>325mg/day) or clopidogrel (\>75mg/day).","healthyVolunteers":false,"sex":"ALL","minimumAge":"18 Years","stdAges":["ADULT","OLDER_ADULT"]},"contactsLocationsModule":{"overallOfficials":[{"name":"Clinical Trials","affiliation":"Hoffmann-La Roche","role":"STUDY_DIRECTOR"}],"locations":[{"city":"Buenos Aires","zip":"1417","country":"Argentina","geoPoint":{"lat":-34.61315,"lon":-58.37723}},{"city":"Córdoba","zip":"5004","country":"Argentina","geoPoint":{"lat":-31.40648,"lon":-64.18853}},{"city":"La Plata","zip":"B1902CMK","country":"Argentina","geoPoint":{"lat":-34.92126,"lon":-57.95442}},{"city":"Mar del Plata","zip":"7600","country":"Argentina","geoPoint":{"lat":-38.00042,"lon":-57.5562}},{"city":"Mendoza","zip":"5500","country":"Argentina","geoPoint":{"lat":-32.88946,"lon":-68.84582}},{"city":"Salta","zip":"4400","country":"Argentina","geoPoint":{"lat":-24.80645,"lon":-65.41999}},{"city":"San Martin","zip":"1650","country":"Argentina","geoPoint":{"lat":-33.08338,"lon":-68.47312}},{"city":"Santa Fe","zip":"03000","country":"Argentina","geoPoint":{"lat":-31.64881,"lon":-60.70868}},{"city":"Santa Fe","zip":"2000","country":"Argentina","geoPoint":{"lat":-31.64881,"lon":-60.70868}},{"city":"Lismore","state":"New South Wales","zip":"2480","country":"Australia","geoPoint":{"lat":-28.81354,"lon":153.2773}},{"city":"Newcastle","state":"New South Wales","zip":"2298","country":"Australia","geoPoint":{"lat":-32.92953,"lon":151.7801}},{"city":"Port Macquarie","state":"New South Wales","zip":"2444","country":"Australia","geoPoint":{"lat":-31.43084,"lon":152.90894}},{"city":"Wahroonga","state":"New South Wales","zip":"2076","country":"Australia","geoPoint":{"lat":-33.71816,"lon":151.11561}},{"city":"Wollongong","state":"New South Wales","zip":"2500","country":"Australia","geoPoint":{"lat":-34.424,"lon":150.89345}},{"city":"Auchenflower","state":"Queensland","zip":"4066","country":"Australia","geoPoint":{"lat":-27.47443,"lon":152.99213}},{"ci