{"protocolSection":{"identificationModule":{"nctId":"NCT07703371","orgStudyIdInfo":{"id":"JSSMC/IEC/24102025/24 NCT/2025"},"organization":{"fullName":"JSS MEDICAL COLLEGE, JSS ACADEMY OF HIGHER EDUCATION AND RESEARCH","class":"OTHER"},"briefTitle":"Kodo Millet Porridge and Its Effects on Gut Health and Metabolic Syndrome","officialTitle":"Impact of Dietary Fiber-Rich Kodo Millet Porridge Supplementation on Gut Microbiome and Metabolic Syndrome","acronym":"KMGMS"},"statusModule":{"statusVerifiedDate":"2026-07","overallStatus":"RECRUITING","expandedAccessInfo":{"hasExpandedAccess":false},"startDateStruct":{"date":"2026-06-01","type":"ACTUAL"},"primaryCompletionDateStruct":{"date":"2026-10-16","type":"ESTIMATED"},"completionDateStruct":{"date":"2026-11-16","type":"ESTIMATED"},"studyFirstSubmitDate":"2026-06-30","studyFirstSubmitQcDate":"2026-07-11","studyFirstPostDateStruct":{"date":"2026-07-14","type":"ACTUAL"},"lastUpdateSubmitDate":"2026-07-11","lastUpdatePostDateStruct":{"date":"2026-07-14","type":"ACTUAL"}},"sponsorCollaboratorsModule":{"responsibleParty":{"type":"PRINCIPAL_INVESTIGATOR","investigatorFullName":"Prerana S Bhat","investigatorTitle":"PhD Scholar and Principal Investigator, Department of Biochemistry","investigatorAffiliation":"JSS MEDICAL COLLEGE, JSS ACADEMY OF HIGHER EDUCATION AND RESEARCH"},"leadSponsor":{"name":"JSS MEDICAL COLLEGE, JSS ACADEMY OF HIGHER EDUCATION AND RESEARCH","class":"OTHER"}},"oversightModule":{"oversightHasDmc":false,"isFdaRegulatedDrug":false,"isFdaRegulatedDevice":false},"descriptionModule":{"briefSummary":"Dietary fiber are components in foods that are not digested by human gastrointestinal enzymes (alpha amylase and alpha glucosidase) but are instead broken down and fermented by gut microbes. The byproducts generated during fermentation in the large intestine, primarily short-chain fatty acids (SCFA), bile acids, indoles, and their derivatives, circulate through the circulatory system to the liver, lungs, brain, adipose tissue, and muscles, where they modulate metabolism (suppress lipogenesis and alleviate insulin resistance) and immune function. Individuals who are overweight or obese frequently exhibit gut dysbiosis, characterized by lower SCFA producing commensals. This condition predisposes them to metabolic disorders such as insulin resistance, dyslipidemia, and hypertension, and contributes to conditions including type 2 diabetes, cardiovascular disease, and metabolic dysfunction-associated steatotic liver disease. Preclinical and clinical research have demonstrated that the consumption of fiber-rich foods maintains or restores gut microbiota health and diminishes the risk of metabolic disorders. Kodo millet (Paspalum scrobiculatum), a small millet, is rich in dietary fiber and we have developed a palatable kodo millet porridge beverage enriched with polyphenols and dietary fiber. The purpose of this study is to examine the effects of consuming Kodo millet porridge beverage as a nutritional supplement for 3 months, on gut microbiome richness (composition and diversity) and metabolic health in overweight or obese people.","detailedDescription":"This single-center, open-label, pre-post interventional trial enrolls 50 people with a BMI ≥ 25 kg/m² (overweight or obese) and no previous history of cardiovascular, renal, or neurological conditions to consume 200 ml of Kodo millet porridge daily for 12 weeks. The study will examine pre- and post-intervention alterations in individual gut microbiota composition through 16S sequencing, as well as circulatory levels of short-chain fatty acids (SCFA), glycemia, lipidemia, triglyceride-glucose index (a measure of insulin resistance), plasma antioxidant capacity, and markers of oxidative stress and inflammation."},"conditionsModule":{"conditions":["Obesity & Overweight","Metabolic Syndrome","Gut Dysbiosis","Insulin Resistance","Dyslipidemia"],"keywords":["Kodo Millet","Dietary Fiber","Gut Microbiome","Short-Chain Fatty Acids","16S rRNA Sequencing","Metabolic Syndrome","Obesity","Gut Dysbiosis","Dyslipidemia","Glycemia","Prebiotic","Small Millet","Porridge","Antioxidant","Inflammation"]},"designModule":{"studyType":"INTERVENTIONAL","phases":["NA"],"designInfo":{"allocation":"NA","interventionModel":"SINGLE_GROUP","interventionModelDescription":"All 50 enrolled participants receive the same intervention - 200 ml of Kodo millet porridge daily for 12 weeks. There is no comparator or control arm. Outcomes are assessed using a pre-post (before and after) design.","primaryPurpose":"PREVENTION","maskingInfo":{"masking":"NONE"}},"enrollmentInfo":{"count":50,"type":"ESTIMATED"}},"armsInterventionsModule":{"armGroups":[{"label":"Kodo Millet Porridge Intervention","type":"EXPERIMENTAL","description":"Participants consume 200 ml of Kodo millet porridge (5% Kodo millet by weight) daily for 12 weeks, 6 days per week, served at 10-11 AM","interventionNames":["Dietary Supplement: Kodo Millet Porridge Beverage"]}],"interventions":[{"type":"DIETARY_SUPPLEMENT","name":"Kodo Millet Porridge Beverage","description":"200 ml of standardized Kodo millet porridge enriched with dietary fiber and polyphenols, consumed once daily for 12 weeks (6 days/week). Prepared under controlled conditions and served warm in a disposable paper cup via thermoflask","armGroupLabels":["Kodo Millet Porridge Intervention"]}]},"outcomesModule":{"primaryOutcomes":[{"measure":"Change in Gut Microbiota Composition and Diversity","description":"Assessment of gut microbiota composition and diversity via 16S rRNA sequencing of stool samples collected at baseline, and week 12","timeFrame":"Baseline, and Week 12"}],"secondaryOutcomes":[{"measure":"Change in Body Mass Index (BMI)","description":"BMI will be calculated from measured height and weight (kg/m²)","timeFrame":"Baseline, Week 6 and Week 12"},{"measure":"Change in Waist-to-Hip Ratio","description":"Waist circumference divided by hip circumference, both measured in centimeters (ratio)","timeFrame":"Baseline, Week 6, and Week 12"},{"measure":"Change in Fasting Blood Glucose","description":"Fasting plasma glucose level (mg/dL)","timeFrame":"Baseline, Week 6, and Week 12"},{"measure":"Change in Blood Lipid Profile","description":"Total cholesterol, LDL cholesterol, HDL cholesterol, and triglycerides (mg/dL)","timeFrame":"Baseline, Week 6, and Week 12"},{"measure":"Change in Triglyceride-Glucose (TyG) Index","description":"TyG index calculated using fasting triglycerides and fasting glucose values","timeFrame":"Baseline, Week 6, and Week 12"},{"measure":"Change in Blood Pressure","description":"Systolic and diastolic blood pressure (mmHg)","timeFrame":"Systolic and diastolic blood pressure (mmHg)"},{"measure":"Change in Serum Antioxidant Status","description":"Serum lipid peroxidation assessed via C11-BODIPY (or C11 dye-based) fluorescence assay (Relative fluorescence units)","timeFrame":"Baseline, Week 6, and Week 12"},{"measure":"Change in Glycated Hemoglobin (HbA1c)","description":"HbA1c measured in serum (%)","timeFrame":"Baseline, Week 6, and Week 12"},{"measure":"Change in High-Sensitivity C-Reactive Protein (hs-CRP)","description":"Serum hs-CRP concentration (mg/L)","timeFrame":"Baseline, Week 6, and Week 12"},{"measure":"Change in Serum Inflammatory Cytokines (IL-6, TNF-alpha, IL-10, IFN-gamma)","description":"Serum concentrations of interleukin-6 (IL-6), tumor necrosis factor-alpha (TNF-α), interleukin-10 (IL-10), and interferon-gamma (IFN-γ) measured via ELISA (pg/mL)","timeFrame":"Baseline, Week 6, and Week 12"},{"measure":"Change in Serum Zonulin/ZO-1 (Tight Junction Protein) Levels","description":"Serum ZO-1 concentration measured via ELISA, as a marker of intestinal permeability (ng/mL)","timeFrame":"Baseline, Week 6, and Week 12"},{"measure":"Change in Serum Hemoglobin","description":"Hemoglobin concentration measured via standard hematology analyzer (g/dL)","timeFrame":"Baseline, Week 6, and Week 12"},{"measure":"Change in Hematocrit","description":"Hematocrit measured via standard hematology analyzer (%)","timeFrame":"Baseline, Week 6, and Week 12"},{"measure":"Change in Total Leukocyte Count","description":"Total leukocyte (white blood cell) count measured via standard hematology analyzer (cells/µL)","timeFrame":"Baseline, Week 6, and Week 12"},{"measure":"Change in Platelet Count","description":"Platelet count measured via standard hematology analyzer (×10³/µL)","timeFrame":"Baseline, Week 6, and Week 12"},{"measure":"Change in Differential Leukocyte Count","description":"Neutrophil, lymphocyte, monocyte, eosinophil, and basophil percentages measured via standard hematology analyzer (%)","timeFrame":"Baseline, Week 6, and Week 12"}]},"eligibilityModule":{"eligibilityCriteria":"Inclusion Criteria

* Adults aged 20-60 years.
* Willingness to provide informed consent.
* Willingness to consume Kodo millet porridge daily for 12 weeks.
* No planned changes in diet or physical activity during the study.
* Overweight or obese (BMI ≥ 25 kg/m²), placing them at risk for metabolic disorders.

Exclusion Criteria

* Known allergies to millet or any porridge ingredients.
* Individuals who are taking on-counter dietary fiber and probiotics supplements
* History of any chronic gastrointestinal diseases (e.g., IBD, gastritis, irritable bowel syndrome).
* Pregnant or lactating women.
* Antibiotic use in last 3 months.
* Alcohol abuse, more than 2 drink per day
* Presence and usage of medications for any serious chronic illnesses, including uncontrolled diabetes (HbA1c \> 9), cardiovascular disease (aldosterone antagonists, alpha blockers, alpha-beta blockers, anticoagulants, antiplatelets, angiotensin-converting enzyme inhibitors, angiotensin 2 receptor blockers, beta blockers, calcium channel blockers, diuretics, digoxin) , renal disease, neurological or mental disorders, coagulation disorders, and cancer.","healthyVolunteers":false,"sex":"ALL","minimumAge":"20 Years","maximumAge":"60 Years","stdAges":["ADULT"]},"contactsLocationsModule":{"centralContacts":[{"name":"Prerana Shridhar Bhat, MSc","role":"CONTACT","phone":"+918762399079","email":"preranabhat@jssuni.edu.in"},{"name":"Dr. Rajesh Kumar Thimmulappa, PhD","role":"CONTACT","phone":"+91-9972012892","email":"rajeshkt@jssuni.edu.in"}],"overallOfficials":[{"name":"Prerana Shridhar Bhat, MSc","affiliation":"JSS MC,JSS AHER","role":"PRINCIPAL_INVESTIGATOR"}],"locations":[{"facility":"JSS Medical College, JSS Academy of Higher Education & Research(JSSAHER).","status":"RECRUITING","city":"Mysore","state":"Karnataka","zip":"570 015","country":"India","contacts":[{"name":"Prerana Shridhar Bhat, MSc","role":"CONTACT","phone":"+91-8762399079","email":"preranabhat@jssuni.edu.in"},{"name":"Dr. Rajesh Kumar Thimmulappa, PhD","role":"CONTACT","phone":"+91-9972012892","email":"rajeshkt@jsuni.edu.in"},{"name":"Prerana Shridhar Bhat, MSc","role":"PRINCIPAL_INVESTIGATOR"}],"geoPoint":{"lat":12.29791,"lon":76.63925}}]},"referencesModule":{"references":[{"pmid":"37673036","type":"BACKGROUND","citation":"Ni Y, Qian L, Siliceo SL, Long X, Nychas E, Liu Y, Ismaiah MJ, Leung H, Zhang L, Gao Q, Wu Q, Zhang Y, Jia X, Liu S, Yuan R, Zhou L, Wang X, Li Q, Zhao Y, El-Nezami H, Xu A, Xu G, Li H, Panagiotou G, Jia W. Resistant starch decreases intrahepatic triglycerides in patients with NAFLD via gut microbiome alterations. Cell Metab. 2023 Sep 5;35(9):1530-1547.e8. doi: 10.1016/j.cmet.2023.08.00