{"protocolSection":{"identificationModule":{"nctId":"NCT03288987","orgStudyIdInfo":{"id":"BEV.ARY.HR.94 (III)"},"organization":{"fullName":"AryoGen Pharmed Co.","class":"INDUSTRY"},"briefTitle":"Comparing Efficacy and Safety of Stivant (AryoGen Bevacizumab) Versus Avastin in Metastatic Colorectal Cancer","officialTitle":"A Phase III, Randomized, Two-armed, Triple Blinded, Parallel, Active Controlled Non-Inferiority Clinical Trial of Stivant (AryoGen Trastuzumab) Efficacy and Safety in Comparison to Avastin in Metastatic Colorectal Cancer"},"statusModule":{"statusVerifiedDate":"2020-09","overallStatus":"COMPLETED","expandedAccessInfo":{"hasExpandedAccess":false},"startDateStruct":{"date":"2016-10-04","type":"ACTUAL"},"primaryCompletionDateStruct":{"date":"2018-07-30","type":"ACTUAL"},"completionDateStruct":{"date":"2018-07-30","type":"ACTUAL"},"studyFirstSubmitDate":"2017-09-18","studyFirstSubmitQcDate":"2017-09-18","studyFirstPostDateStruct":{"date":"2017-09-20","type":"ACTUAL"},"resultsFirstSubmitDate":"2020-09-15","resultsFirstSubmitQcDate":"2020-12-30","resultsFirstPostDateStruct":{"date":"2021-01-22","type":"ACTUAL"},"lastUpdateSubmitDate":"2020-12-30","lastUpdatePostDateStruct":{"date":"2021-01-22","type":"ACTUAL"}},"sponsorCollaboratorsModule":{"responsibleParty":{"type":"SPONSOR"},"leadSponsor":{"name":"AryoGen Pharmed Co.","class":"INDUSTRY"}},"descriptionModule":{"briefSummary":"This is a Phase III, randomized, two arms, double-blind (patient and assessor blinded), parallel active non inferiority controlled clinical trial with a 2:1 allocation. This trial was conducted to evaluate the efficacy and safety of bevacizumab (produced by AryoGen Pharmed) plus FOLFIRI-3 compared with bevacizumab (Avastin®) plus FOLFIRI-3 in patients with metastatic colorectal cancer (mCRC). Patients who met the following criteria could be recruited to receive the mentioned intervention randomly. Inclusion criteria: male or female aged 18-75 years, mCRC verified histologically, Having one or more bi-dimensionally measurable lesions as defined by Response Evaluation Criteria In Solid Tumors (RECIST) criteria, Was not felt to be amenable to curative resection, With an (ECOG) performance status of ≤ 1, Life expectancy of longer than 3 months, Adequate organ and marrow function, May have received adjuvant therapy for primary colorectal cancer provided that at least 6 months have elapsed from the time the adjuvant therapy was concluded and recurrent disease was documented, Patients with history of hypertension must be well-controlled (blood pressure less than/equal to 150/100), on a stable regimen of anti-hypertensive therapy.","detailedDescription":"This is a Phase III, randomized, two arms, double-blind (patient and assessor blinded), parallel active non inferiority controlled clinical trial with a 2:1 allocation. This trial was conducted to evaluate the efficacy and safety of bevacizumab (produced by AryoGen) plus FOLFIRI-3 compared with bevacizumab (Avastin®) plus FOLFIRI-3 in patients with metastatic colorectal cancer (mCRC). Patients who met the following criteria could be recruited to receive the mentioned intervention randomly. Inclusion criteria: male or female aged 18-75 years, mCRC verified histologically, Having one or more bi-dimensionally measurable lesions as defined by Response Evaluation Criteria In Solid Tumors (RECIST) criteria, Was not felt to be amenable to curative resection, With an (ECOG) performance status of ≤ 1, Life expectancy of longer than 3 months, Adequate organ and marrow function, May have received adjuvant therapy for primary colorectal cancer provided that at least 6 months have elapsed from the time the adjuvant therapy was concluded and recurrent disease was documented, Patients with history of hypertension must be well-controlled (blood pressure less than/equal to 150/100), on a stable regimen of anti-hypertensive therapy. Exclusion criteria: Prior targeted therapy for mCRC, Radiotherapy or surgery for mCRC less than 4 weeks before random assignment, Undergone major surgical procedures or open biopsy within 28 days before the initiation of study treatment, Experienced significant traumatic injury, within 28 days before study entry, Currently using or had recently used therapeutic anticoagulants, thrombolytic therapy, chronic, daily treatment with aspirin (higher than 325 mg/daily), Proteinuria exceeding 500mg/24 h, History or presence of central nervous system metastases, Female patients who are pregnant or lactating, Patients with a history of allergic reactions attributed to compounds of similar chemical or biologic composition to bevacizumab, irinotecan, 5-FU, or leucovorin, Serious non-healing wound, ulcer, or active bone fracture, Myocardial infarction within 6 months before of study enrollment, History of stroke within 6 months before of study enrollment, Unstable symptomatic arrhythmia requiring medication, Clinically significant peripheral vascular disease, Uncontrolled diabetes; Serious active or uncontrolled infection, Inability to comply with study and/or follow-up procedures. The primary endpoint is progression-free survival and overall survival, Objective Response rate, time of treatment failures, adverse events and immunogenicity will be assessed as secondary outcomes."},"conditionsModule":{"conditions":["Metastatic Colorectal Cancer"]},"designModule":{"studyType":"INTERVENTIONAL","phases":["PHASE3"],"designInfo":{"allocation":"RANDOMIZED","interventionModel":"PARALLEL","primaryPurpose":"TREATMENT","maskingInfo":{"masking":"DOUBLE","whoMasked":["PARTICIPANT","INVESTIGATOR"]}},"enrollmentInfo":{"count":126,"type":"ACTUAL"}},"armsInterventionsModule":{"armGroups":[{"label":"Bevacizumab + FOLFIRI-3 (AryoGen Pharmed Bevacizumab)","type":"EXPERIMENTAL","description":"Bevacizumab+FOLFIRI-3 (irinotecan, leucovorin, and 5-FU). Bevacizumab (AryoGen) 5 mg/kg will be administered every 2 weeks.","interventionNames":["Drug: Bevacizumab + FOLFIRI-3"]},{"label":"Bevacizumab + FOLFIRI-3 (Roche Bevacizumab)","type":"ACTIVE_COMPARATOR","description":"Bevacizumab+FOLFIRI-3 (irinotecan, leucovorin, and 5-FU). Bevacizumab (Avastin®) 5 mg/kg will be administered every 2 weeks.","interventionNames":["Drug: Bevacizumab + FOLFIRI-3"]}],"interventions":[{"type":"DRUG","name":"Bevacizumab + FOLFIRI-3","description":"Bevacizumab 5 mg/kg will be administered at day 1 every 2 weeks. Initially, it will be administered as a 90-min infusion. If the first infusion is well tolerated, the second will be delivered as a 60-min infusion, and if the 60-min infusion is well tolerated, all subsequent infusions will be given over 30 minutes. FOLFIRI-3 regimen consists of irinotecan 100 mg/m2 over 1 hour at day 1, leucovorin 400 mg/m2 at day 1 followed by a 46 hour 5-FU continuous infusion (2000 mg/m2) and irinotecan 100 mg/m2 over 1 hour on day 3 will administer. Induction treatment was administrated every 2 weeks until disease progression, unacceptable toxicities, surgical intervention, or withdrawal of consent.","armGroupLabels":["Bevacizumab + FOLFIRI-3 (AryoGen Pharmed Bevacizumab)","Bevacizumab + FOLFIRI-3 (Roche Bevacizumab)"],"otherNames":["FOLFIRI-3 = irinotecan + calcium folinate + 5-fluorouracil"]}]},"outcomesModule":{"primaryOutcomes":[{"measure":"Progression Free Survival (PFS)","description":"PFS is defined as the time from the date of randomization to the first date of documentation progression (per investigator assessment) or death as a result of any cause.","timeFrame":"PFS was measured from the start of chemotherapy to the date of disease progression or to the date of death if no progression whichever came first, assessed up to 12 months"}],"secondaryOutcomes":[{"measure":"Overall Survival (OS)","description":"Overall survival OS was defined as the time from date of randomization to date of death due to any cause","timeFrame":"Up to 12 months"},{"measure":"Objective Response Rate","description":"Tumor response was defined as partial and complete responses, according to the RECIST criteria ( version 1.1). The definitions were as follows: Complete Response (CR), Disappearance of all target lesions; Partial Response (PR), decrease of at least 30% in the lesion that has the largest diameter; Objective Response Rate (ORR) = CR + PR.","timeFrame":"Up to 12 months"},{"measure":"Time to Treatment Failure","description":"Time to treatment failure was defined as the time from the date of randomization to the date of each of the following,

* The treatment modalities did not destroy or modify the cancer cells,
* The tumor either became larger (disease progression) or stayed the same size after treatment,
* Death due to any cause,
* Discontinuation of treatment","timeFrame":"Up to 12 months"},{"measure":"Incidence of the Adverse Events","description":"Safety was assessed on the basis of reports of adverse events, laboratory-test results, and vital sign measurements. Adverse events were categorized According to the Common Toxicity Criteria of the National Cancer Institute, version 5.0, in which a grade of 1 indicates mild adverse events, a grade of 2 moderate adverse events, a grade of 3 serious adverse events, and a grade of 4 life-threatening adverse events","timeFrame":"Up to 12 months"},{"measure":"Number of Positive Anti-drug Antibody (ADA) Samples Among Patients (Immunogenicity)","description":"Anti-drug antibody assessment","timeFrame":"Up to 12 months"}]},"eligibilityModule":{"eligibilityCriteria":"Inclusion Criteria:

* Are male or female aged 18-75 years at the time of signing the informed consent form.
* Have been diagnosed as mCRC verified histologically
* Having one or more bi-dimensionally measurable lesions as defined by Response Evaluation Criteria In Solid Tumors (RECIST) criteria,
* Was not felt to be amenable to curative resection,
* With an Eastern Cooperative Oncology Group (ECOG) performance status of ≤ 1
* Life expectancy of longer than 3 months ( clinical assessment)
* Adequate organ and marrow function as defined below:

  * Absolute neutrophil count (ANC) greater than/equal to 1,500/mm3;
  * Platelets greater than/equal to 100,000/ mm3;
  * Hemoglobin greater than/equal to 9 gm/dl (may be transfused to maintain or exceed this level);
  * Total bilirubin less than/equal to 1.5 within institutional upper limit of normal (IULN);
  * Aspartate aminotransferase (AST or SGOT)/alanine aminotransferase (ALT or SGPT) less than/equal to 2.5 times IULN, or less than/equal to 5 times IULN if known liver metastases;
* May have received adjuvant therapy for primary colorectal cancer provided that at least 6 months have elapsed from the time the adjuvant therapy was concluded and recurrent disease was documented
* Patients with history of hypertension must be well-controlled (blood pressure less than/equal to 150/100), on a stable regimen of anti-hypertensive therapy.

Exclusion Criteria:

* Prior targeted therapy for mCRC
* Radiotherapy or surgery for mCRC less than 4 weeks before random assignment.
* Undergone major surgical procedures or open biopsy within 28 days before the initiation of study treatment
* Experienced significant traumatic injury, within 28 days before study entry
* Currently using or had recently used therapeutic anticoagulants, thrombolytic therapy, chronic, daily treatment with aspirin (higher than 325 mg/daily). (Patients may have prophylactic use of low molecular weight heparin, however therapeutic use of heparin or low molecular weight heparin is not acceptable)
* Proteinuria exceeding 500mg/24 h
* History or presence of central nervous system metastases
* Female patients who are pregnant or lactating
* Patients with a history of allergic reactions attributed to compounds of similar chemical or biologic composition to bevacizumab, irinotecan, 5-FU, or leucovorin
* Serious non-healing wound, ulcer, or active bone fracture
* Myocardial infarction within 6 months before of study enrollment;
* History of stroke within 6 months before of study enrollment;
* Clinically significant peripheral vascular disease;
* Uncontrolled diabetes; Serious active or uncontrolled infection
* Inability to comply with study and/or follow-up procedures","healthyVolunteers":false,"sex":"ALL","minimumAge":"18 Years","maximumAge":"75 Years","stdAges":["ADULT","OLDER_ADULT"]},"contactsLocationsModule":{"overallOfficials":[{"name":"Hamid Rezvani, M.D","affiliation":"Shahid Beheshti University of Medical Sciences","role":"PRINCIPAL_INVESTIGATOR"}],"locations":[{"facility":"Shafa Hospital","city":"Ahvāz","country":"Iran","geoPoint":{"lat":31.31901,"lon":48.6842}},{"facility":"Shahid Beheshti Hospital","city":"Hamadan","country":"Iran","geoPoint":{"lat":34.79922,"lon":48.51456}},{"facility":"Saba Clinic","city":"Isfahan","country":"Iran","geoPoint":{"lat":32.65246,"lon":51.67462}},{"facility":"Sheikh Mofid","city":"Isfahan","country":"Iran","geoPoint":{"lat":32.65246,"lon":51.67462}},{"facility":"Payandeh Clinic","city":"Kermanshah","country":"Iran","geoPoint":{"lat":34.31417,"lon":47.065}},{"facility":"Shazad Clinic","city":"Kermanshah","country":"Iran","geoPoint":{"lat":34.31417,"lon":47.065}},{"facility":"Imam Reza Hospital","city":"Mashhad","country":"Iran","geoPoint":{"lat":36.29807,"lon":59.60567}},{"facility":"Qaem Hospital","city":"Mashhad","country":"Iran","geoPoint":{"lat":36.29807,"lon":59.60567}},{"facility":"Rasool Hospital","city":"Rasht","country":"Iran","geoPoint":{"lat":37.27611,"lon":49.58862}},{"facility":"Razi Hospital","city":"Rasht","country":"Iran","geoPoint":{"lat":37.27611,"lon":49.58862}},{"facility":"Namazi Hospital","city":"Shiraz","country":"Iran","geoPoint":{"lat":29.61031,"lon":52.53113}},{"facility":"Firoozgar Hospital","city":"Tehran","country":"Iran","geoPoint":{"lat":35.69439,"lon":51.42151}},{"facility":"Imam Khomeini Hospital","city":"Tehran","country":"Iran","geoPoint":{"lat":35.69439,"lon":51.42151}},{"facility":"Imam Reza Hospital (501 Artesh)","city":"Tehran","country":"Iran","geoPoint":{"lat":35.69439,"lon":51.42151}},{"facility":"Masih Daneshvari Hospital","city":"Tehran","country":"Iran","geoPoint":{"lat":35.69439,"lon