{"protocolSection":{"identificationModule":{"nctId":"NCT04472104","orgStudyIdInfo":{"id":"H19-02480"},"organization":{"fullName":"University of British Columbia","class":"OTHER"},"briefTitle":"BREast Cancer And Sexuality Treatment","officialTitle":"Mindfulness-based Treatment for Sexual Difficulties Following Breast Cancer","acronym":"BREAST"},"statusModule":{"statusVerifiedDate":"2022-05","overallStatus":"COMPLETED","expandedAccessInfo":{"hasExpandedAccess":false},"startDateStruct":{"date":"2020-01-06","type":"ACTUAL"},"primaryCompletionDateStruct":{"date":"2022-12-01","type":"ACTUAL"},"completionDateStruct":{"date":"2023-04-01","type":"ACTUAL"},"studyFirstSubmitDate":"2019-11-19","studyFirstSubmitQcDate":"2020-07-13","studyFirstPostDateStruct":{"date":"2020-07-15","type":"ACTUAL"},"lastUpdateSubmitDate":"2023-05-08","lastUpdatePostDateStruct":{"date":"2023-05-10","type":"ACTUAL"}},"sponsorCollaboratorsModule":{"responsibleParty":{"type":"PRINCIPAL_INVESTIGATOR","investigatorFullName":"Lori Brotto","investigatorTitle":"Principal Investigator","investigatorAffiliation":"University of British Columbia"},"leadSponsor":{"name":"University of British Columbia","class":"OTHER"},"collaborators":[{"name":"University of Calgary","class":"OTHER"}]},"oversightModule":{"oversightHasDmc":false,"isFdaRegulatedDrug":false,"isFdaRegulatedDevice":false},"descriptionModule":{"briefSummary":"The purpose of this project is to compare the effects of a group mindfulness treatment versus a group sex education on sexual desire, sexual distress, and sexual pain in breast cancer (BrCa) survivors. Participants will be randomly assigned to either 8 weekly sessions of a group mindfulness-based treatment or 8 weekly sessions of a sex education group. Groups will consist of approximately 8 breast cancer survivors and will be led by 2 trained therapists. Participants will complete four assessments (involving a clinician administered interview and standardized questions): pre-treatment, post- treatment, and 6 month follow up."},"conditionsModule":{"conditions":["Sexual Dysfunction"]},"designModule":{"studyType":"INTERVENTIONAL","phases":["NA"],"designInfo":{"allocation":"RANDOMIZED","interventionModel":"PARALLEL","interventionModelDescription":"3-year, randomized, unblinded, two-site, controlled trial of 8 weekly sessions of group Mindfulness-Based Cognitive Therapy for sexuality (MBCT-S) vs. 8 weekly sessions of a sex education treatment.","primaryPurpose":"TREATMENT","maskingInfo":{"masking":"SINGLE","maskingDescription":"Those doing data analysis are blind","whoMasked":["OUTCOMES_ASSESSOR"]}},"enrollmentInfo":{"count":118,"type":"ACTUAL"}},"armsInterventionsModule":{"armGroups":[{"label":"MBCT-S","type":"ACTIVE_COMPARATOR","description":"Mindfulness-Based Cognitive Therapy for sexuality (MBCT-S) which incorporates several empirically supported therapeutic approaches, integrating elements of education, mindfulness meditation skills, and sex therapy.","interventionNames":["Behavioral: MBCT-S"]},{"label":"SexEd","type":"ACTIVE_COMPARATOR","description":"Sexuality education on sexual desire, sexual distress, and sexual pain.","interventionNames":["Behavioral: SexEd"]}],"interventions":[{"type":"BEHAVIORAL","name":"MBCT-S","description":"Group mindfulness treatment for sexual desire, sexual distress, and sexual pain in breast cancer (BrCa) survivors.","armGroupLabels":["MBCT-S"]},{"type":"BEHAVIORAL","name":"SexEd","description":"Group sex education on sexual desire, sexual distress, and sexual pain in breast cancer (BrCa) survivors.","armGroupLabels":["SexEd"]}]},"outcomesModule":{"primaryOutcomes":[{"measure":"A Change from Baseline Sexual Interest and Desire Female (SIDI-F) Score at 2 weeks' post-treatment","description":"Sexual desire will be measured with the 13-item Sexual Interest and Desire Inventory which is a 14-item questionnaire that assesses sexual desire in women which includes one non-scored item assessing intercourse frequency. Possible total scores range from 0 - 51, with higher scores indicating higher levels of sexual functioning.","timeFrame":"Baseline/T1 is within 2 weeks pre-treatment and T2 is within 2 weeks post-treatment"},{"measure":"A Change from Baseline Sexual Interest and Desire Female (SIDI-F) Score at 6 month follow-up","description":"Sexual desire will be measured with the 13-item Sexual Interest and Desire Inventory which is a 14-item questionnaire that assesses sexual desire in women which includes one non-scored item assessing intercourse frequency. Possible total scores range from 0 - 51, with higher scores indicating higher levels of sexual functioning.","timeFrame":"Baseline/T1 is within 2 weeks pre-treatment and T3 is at 6 month follow-up"},{"measure":"No Change in Sexual Interest and Desire Female (SIDI-F) Score from 2 weeks' post-treatment (T2) and at 6 month follow-up (T3)","description":"Sexual desire will be measured with the 13-item Sexual Interest and Desire Inventory which is a 14-item questionnaire that assesses sexual desire in women which includes one non-scored item assessing intercourse frequency. Possible total scores range from 0 - 51, with higher scores indicating higher levels of sexual functioning.","timeFrame":"T2 is within 2 weeks post-treatment and T3 is at 6 month follow-up"},{"measure":"A Change from Baseline Female Sexual Distress Scale - Revised (FSDS-R) Score at 2 weeks' post-treatment","description":"Sexual distress will be assessed using the Female Sexual Distress Scale - Revised which is a 13-item scale where scores on the scale range from 0 - 52, where higher scores represent higher levels of distress.","timeFrame":"Baseline/T1 is within 2 weeks pre-treatment and T2 is within 2 weeks post-treatment"},{"measure":"A Change from Baseline Female Sexual Distress Scale - Revised (FSDS-R) Score at 6 month follow-up","description":"Sexual distress will be assessed using the Female Sexual Distress Scale - Revised which is a 13-item scale where scores on the scale range from 0 - 52, where higher scores represent higher levels of distress.","timeFrame":"Baseline/T1 is within 2 weeks pre-treatment and T3 is at 6 month follow-up"},{"measure":"No Change in Female Sexual Distress Scale - Revised (FSDS-R) Score from T2 at 2 weeks' post-treatment and at 6 month follow-up","description":"Sexual distress will be assessed using the Female Sexual Distress Scale - Revised which is a 13-item scale where scores on the scale range from 0 - 52, where higher scores represent higher levels of distress.","timeFrame":"T2 is within 2 weeks post-treatment and T3 is at 6 month follow-up"},{"measure":"A Change from Baseline Sexual Pain Rating Score at 2 weeks' post-treatment","description":"Numeric Rating Scale of 0-10 (from no pain to worst possible pain) in response to vaginal penetration.","timeFrame":"Baseline/T1 is within 2 weeks pre-treatment and T2 is within 2 weeks post-treatment"},{"measure":"A Change from Baseline Sexual Pain Rating Score at 6 month follow-up","description":"Numeric Rating Scale of 0-10 (from no pain to worst possible pain) in response to vaginal penetration.","timeFrame":"Baseline/T1 is within 2 weeks pre-treatment and T3 is at 6 month follow-up"},{"measure":"No Change in Sexual Pain Rating Score from 2 weeks' post-treatment and at 6 month follow-up","description":"Numeric Rating Scale of 0-10 (from no pain to worst possible pain) in response to vaginal penetration.","timeFrame":"T2 is within 2 weeks post-treatment and T3 is at 6 month follow-up"}]},"eligibilityModule":{"eligibilityCriteria":"Inclusion Criteria:

* Women over the age of majority, with a history of breast cancer and who are at least 3 months following the end of their treatment
* Fluent in English
* Exceed the clinical cut-off for sexual distress (Female Sexual Distress Scale).
* Women who are, and who are not, in a relationship will be eligible as long as they have engaged in sexual activity either alone or with a sexual partner in the past 6 months, or as long as they indicate a willingness to engage in sexual activity (alone or with a sexual partner) during the time period of the study.

Exclusion Criteria:

* Active cancer treatment (e.g. chemotherapy or radiation, not including endocrine or maintenance therapies provided they remain constant for the study duration), or scheduled breast reconstruction during the study period.
* Borderline Personality Disorder or other psychiatric or medical conditions that preclude the ability to fully participate in the group sessions, assessments, and homework.
* In order to determine whether any changes in symptoms are a result of participation in the intervention, women must also agree to 1) not make changes to or commence vaginal interventions (e.g., topical hormone treatments, vaginal moisturizers, vaginal dilation) or 2) engage in other treatments for sexual difficulties (e.g., sex therapy), for 2 weeks prior to the baseline assessment until 2 weeks following the final intervention session.","healthyVolunteers":false,"sex":"FEMALE","minimumAge":"19 Years","stdAges":["ADULT","OLDER_ADULT"]},"contactsLocationsModule":{"locations":[{"facility":"UBC Sexual Health Lab, Vancouver Hospital","city":"Vancouver","state":"British Columbia","zip":"V5M 1M9","country":"Canada","geoPoint":{"lat":49.24966,"lon":-123.11934}}]}},"derivedSection":{"miscInfoModule":{"versionHolder":"2026-10-08"},"conditionBrowseModule":{"meshes":[{"id":"D012735","term":"Sexual Dysfunction, Physiological"}],"ancestors":[{"id":"D000091662","term":"Genital Diseases"},{"id":"D000091642","term":"Urogenital Diseases"}]}},"hasResults":false},
