{"protocolSection":{"identificationModule":{"nctId":"NCT07410052","orgStudyIdInfo":{"id":"11-385-28-01"},"organization":{"fullName":"Center for Health Sciences, Serbia","class":"OTHER"},"briefTitle":"Microbiome-Targeted Enhancement of Neurocognition With Probiotics-Riboflavin Combination","officialTitle":"Microbiome-Targeted Enhancement of Neurocognition With Probiotics-Riboflavin Combination (MENTOR)","acronym":"MENTOR"},"statusModule":{"statusVerifiedDate":"2026-02","overallStatus":"NOT_YET_RECRUITING","expandedAccessInfo":{"hasExpandedAccess":false},"startDateStruct":{"date":"2026-04-15","type":"ESTIMATED"},"primaryCompletionDateStruct":{"date":"2027-07-15","type":"ESTIMATED"},"completionDateStruct":{"date":"2027-08-15","type":"ESTIMATED"},"studyFirstSubmitDate":"2026-02-07","studyFirstSubmitQcDate":"2026-02-07","studyFirstPostDateStruct":{"date":"2026-02-13","type":"ACTUAL"},"lastUpdateSubmitDate":"2026-02-07","lastUpdatePostDateStruct":{"date":"2026-02-13","type":"ACTUAL"}},"sponsorCollaboratorsModule":{"responsibleParty":{"type":"SPONSOR"},"leadSponsor":{"name":"Center for Health Sciences, Serbia","class":"OTHER"}},"oversightModule":{"isFdaRegulatedDrug":false,"isFdaRegulatedDevice":false},"descriptionModule":{"briefSummary":"This randomized, double-blind, placebo-controlled trial will evaluate whether 12 weeks of supplementation with the probiotic Lactobacillus rhamnosus GG combined with colon-delivered riboflavin will improve cognitive performance and brain physiology in older adults with memory complaints. The study will assess changes in cognitive outcomes together with neurophysiological markers to explore potential gut-brain axis mechanisms. Through its rigorous design, the trial will aim to determine whether targeted modulation of the intestinal environment can support brain function and cognitive health in aging."},"conditionsModule":{"conditions":["Cognitive Deficits, Mild"],"keywords":["Bioenergetics","Sleep quality","Cognition","Oxygenation"]},"desi